1	package org.springframework.samples.petclinic.rest.validation;
2	
3	/**
4	 * Normalizes free-form telephone input into canonical E.164 form.
5	 *
6	 * <p>Rules:
7	 * <ul>
8	 *   <li>Spaces, dashes, brackets and any other non-digit separators are stripped.</li>
9	 *   <li>A leading {@code '+'} means the country code is already present and is kept.</li>
10	 *   <li>Otherwise the Australian country code {@code +61} is assumed and a single
11	 *       leading {@code '0'} is dropped from the national digits.</li>
12	 *   <li>The result must carry between 8 and 15 digits after the {@code '+'}, otherwise
13	 *       it cannot form a valid E.164 number.</li>
14	 * </ul>
15	 *
16	 * <p>For example {@code '0412 345 678'} becomes {@code '+61412345678'} and
17	 * {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
18	 */
19	public final class TelephoneNormalizer {
20	
21	    private TelephoneNormalizer() {
22	    }
23	
24	    /**
25	     * Converts raw telephone input to E.164, or returns {@code null} when the input is
26	     * {@code null} or cannot form a valid E.164 number.
27	     *
28	     * @param raw the raw telephone input (may be {@code null})
29	     * @return the E.164 string (e.g. {@code '+61412345678'}), or {@code null}
30	     */
31	    public static String toE164(String raw) {
32	        if (raw == null) {
33	            return null;
34	        }
35	        boolean hasCountryCode = raw.trim().startsWith("+");
36	        String digits = raw.replaceAll("\\D", "");
37	        if (!hasCountryCode) {
38	            if (digits.startsWith("0")) {
39	                digits = digits.substring(1);
40	            }
41	            digits = "61" + digits;
42	        }
43	        if (digits.length() < 8 || digits.length() > 15) {
44	            return null;
45	        }
46	        return "+" + digits;
47	    }
48	
49	    /**
50	     * @param raw the raw telephone input (may be {@code null})
51	     * @return {@code true} when {@code raw} is {@code null} (absence is handled elsewhere)
52	     *         or can form a valid E.164 number
53	     */
54	    public static boolean isValid(String raw) {
55	        return raw == null || toE164(raw) != null;
56	    }
57	}
